#' Generate predictions of cave entrances as points, from a LAS file of interest
#' 
#' @param method One of "simple" (predictions generated by mechanistic thresholds) or "model" (predictions generated by machine learning, requires a model object).
#' @param las A lidR LAS object to derive predictions.
#' @param metric_thresholds Only specify if method="simple". Should be named list like list(depth_plane=1, depth_mean=1.5). Possible metrics are depth_plane, depth_mean, depth_half_radius_mean, depth_w_mean, slope, intensity, return_number, R, G, B, NIR.
#' @param radius Only specify if method="simple", otherwise overwritten by model radius. Radius to define neighborhood of each cave, in meters. Default value is 10. 
#' @param model Only specify if method="model". Either the ID (character) of a corrected cave dataset whose model should be loaded from "output", or a model object created directly with train_model().
#' @param score_threshold Only specify if method="model". Threshold to filter model output.
#' @param isolated_policy One of "include" (to include isolated points in inspection), "autolabel" (to automatically label isolated points as "1") or "exclude" (to exclude isolated points completely). "include" is only allowed if inspection=TRUE.
#' @param remove_edges Logical, default TRUE. Remove candidate points from edges, which are usually false positives?
#' @param remove_waterlines Logical, default TRUE. Remove candidate points from waterlines, which are usually false positives?
#' @param inspection Logical, default TRUE. Do one-by-one inspection or directly export all predictions without labels? If FALSE points get labeled with "3".
#'
#' @return
#' This function doesn't return any object.
#' 
#' @details
#' Generates candidate points of entrance locations in a chosen area, using either a ‘simple’ metric 
#' thresholding method or a more flexible ‘model’ approach. The algorithm initially subsets the 
#' entire point cloud to ‘local minima’ points – those with the minimum height in their respective 
#' neighbourhoods, defined using an iteratively offset grid. This is a computationally cheap way to 
#' drastically reduce the number of points to be processed, while keeping all points which could mark 
#' the bottom of pits. Optionally, points located at the edge of the LiDAR tile or inside waterlines 
#' can be excluded, since these are common false positives. For each point, a selected set of metrics 
#' is computed, which are then used to filter candidates, either against simple thresholds, or with 
#' likelihood scores resulting from projecting a model on the metrics. Finally, nearby positives are 
#' aggregated and the optional case-by-case user inspection starts. Inspection of model output is 
#' strongly encouraged, as it can greatly refine the results for a successful field trip. If 
#' inspection is done, it is also recommended to use relatively low score or metric threshold 
#' parameters to ensure no points with great potential are lost due to noise in surrounding terrain. 
#' Final cave entrance predictions are exported in both KML and Shapefile formats. The KML is meant 
#' to facilitate compatibility with standard GPS apps for fieldwork – each point carries a simple tag 
#' with the label attached – while the Shapefile is meant for GIS databasing and analysis: the export 
#' includes informative fields such as method, settings used to generate the predictions, and 
#' point-wise information.
#'
#' @examplesIf FALSE
#' # get data
#' my_las <- lidR::readLAS(here::here("data", "LIDAR_tiles", "LO-149288-06-2024_v01.laz"))
#'
#' # method = "model"
#' get_predictions(
#'   method = "model",
#'   las = my_las,
#'   model = '20260810122226',
#'   score_threshold = 0.5,
#'   isolated_policy = "include",
#'   remove_edges = TRUE,
#'   remove_waterlines = TRUE,
#'   inspection = TRUE
#' )
#'
#' # method = "simple"
#' get_predictions(
#'   method = "simple",
#'   las = my_las,
#'   metric_thresholds = list(depth_plane=2),
#'   radius = 10,
#'   isolated_policy = "include",
#'   remove_edges = TRUE,
#'   remove_waterlines = TRUE,
#'   inspection = TRUE
#' )
#'
#' @importFrom randomForest randomForest
#'
#' @export
get_predictions <- function(
    method = c("simple", "model"), 
    las,
    metric_thresholds = NULL,
    radius = 10,
    model = NULL,
    score_threshold = NULL,
    isolated_policy = c("include", "autolabel", "exclude"),
    remove_edges = TRUE,
    remove_waterlines = TRUE,
    inspection = TRUE
) {
  
  # CHECK ARGUMENTS ------------------------------------------------------------------------------------------------
  
  method <- match.arg(method)
  isolated_policy <- match.arg(isolated_policy)
  
  coll <- checkmate::makeAssertCollection()
  
  # unconditional checks
  checkmate::assert_class(las, "LAS", add = coll)
  checkmate::assert_number(radius, lower = 0, finite = TRUE, add = coll)
  checkmate::assert_flag(remove_edges, add = coll)
  checkmate::assert_flag(remove_waterlines, add = coll)
  checkmate::assert_flag(inspection, add = coll)
  
  # conditional checks: method == "simple" 
  if (method == "simple") {
    checkmate::assert_list(
      metric_thresholds,
      types = "numeric", names = "unique", min.len = 1,
      add = coll
    )
    if (!is.null(model)) {
      coll$push("`model` must not be supplied when method = 'simple'.")
    }
    if (!is.null(score_threshold)) {
      coll$push("`score_threshold` must not be supplied when method = 'simple'.")
    }
  }
  
  # conditional checks: method == "model"
  if (method == "model") {
    checkmate::assert(
      checkmate::check_string(model, min.chars = 1),
      checkmate::check_class(model, "randomForest"),
      combine = "or",
      add = coll
    )
    checkmate::assert_number(score_threshold, lower = 0, upper = 1, add = coll)
    if (!is.null(metric_thresholds)) {
      coll$push("`metric_thresholds` must not be supplied when method = 'model'.")
    }
  }
  
  # conditional check unrelated to method
  if (isolated_policy == "include" && !inspection) {
    coll$push("isolated_policy = 'include' only makes sense when inspection = TRUE.")
  }
  
  checkmate::reportAssertions(coll)
  
  
  
  # FIRST STEPS ------------------------------------------------------------------------------------------------
  
  # subset points classified as "ground" (2) and as "noise" (7)
  # cave entrances are frequently classified as "noise", which means low points
  las_sub <- las[ las$Classification == 2 | las$Classification == 7 ]

  # resolve model argument: if id string load from disk, then recover radius and metrics
  if (method == "model") {
    if (checkmate::test_string(model)) {
      load( here::here("output", paste0("corrected_cave_dataset_", model), "model.Rdata" ))
      # gets model, overwriting the id string with the actual randomForest object
    }
    if (is.null(attr(model, "metrics")) || is.null(attr(model, "radius"))) {
      stop("`model` is missing required 'metrics'/'radius' attributes - was it produced by train_model()?")
    }
    radius <- attr(model, "radius")
    message("Using radius of ", radius, "m that was used to train the model.")
  }
  
  # define color scheme for rgl plots
  class_colors <- c(
    "1" = "grey", 
    "2" = "black", 
    "3" = "lightgreen",
    "4" = "green",
    "5" = "darkgreen",
    "6" = "red", 
    "7" = "purple", 
    "9" = "blue", 
    "26" = "red"
  )
  
  
  
  # SUBSET POINTS WHICH ARE LOCAL MINIMA ------------------------------------------------------------------------------------------------
  # this is a computationally cheap way to subsample the point cloud for later point-by-point analysis
  
  # define grid offset scheme
  shifts <- expand.grid(dx = c(0,2,4,6,8), dy = c(0,2,4,6,8) ) #TUNE grid is offset 2m each iteration, either on x or y
  
  # get minima for each offset grid
  minima <- lapply( 1:nrow(shifts), function(i) {
    
    # shift coordinates
    las_shifted <- las_sub
    las_shifted@data$X <- las_shifted@data$X + shifts$dx[i]
    las_shifted@data$Y <- las_shifted@data$Y + shifts$dy[i]
    
    # get minima
    pts <- lidR::decimate_points(las_shifted, lidR::lowest( 10 )) #TUNE 10x10m grid. Successful detection assumes no points lower than entrance bottom in same cell as cave. This case might happen on steep slopes, but its likely that at least in one grid iteration the entrance is in a corner of cell and is classified as the minimum.
    
    # shift back
    pts@data$X <- pts@data$X - shifts$dx[i]
    pts@data$Y <- pts@data$Y - shifts$dy[i]
    
    pts
  })
  
  # merge minima from all offset iterations
  all_minima <- do.call(rbind, minima)
  
  # eliminate duplicate minima
  duplicated_minima <- duplicated(all_minima@data[, c("X","Y","Z")])
  all_minima <- all_minima[ !duplicated_minima , ]
  
  message("Local minima points were obtained.")
  
  
  
  # EXCLUDE EDGE MINIMA ------------------------------------------------------------------------------------------------
  # these are usual false positives
  
  if (remove_edges){
    
    # get mask 
    ed <- 1 #TUNE excludes 1m edge
    e <- terra::ext(all_minima)
    mask <- terra::ext(
      terra::xmin(e) + ed,
      terra::xmax(e) - ed,
      terra::ymin(e) + ed,
      terra::ymax(e) - ed
    )
    
    # conversions from spatextent to st vector
    mask <- terra::as.polygons(mask)    
    mask <- sf::st_as_sf(mask) 
    sf::st_crs(mask) <- lidR::st_crs(all_minima)
    
    # crop
    all_minima <- lidR::clip_roi( all_minima, mask)
    
    message("Edge points were removed.")
  }

  
  
  # EXCLUDE WATERLINE MINIMA ------------------------------------------------------------------------------------------------
  # these are usual false positives
  
  if (remove_waterlines){
    
    # generate DTM, flow accumulation raster and derive waterline pixels
    dtm <- lidR::rasterize_terrain(las_sub, res = 1, algorithm = lidR::tin())
    flowdir <- terra::terrain(dtm, "flowdir")
    flowaccum <- terra::flowAccumulation(flowdir)
    waterlines <- flowaccum > 2000 #TUNE
    
    # convert raster to vector points
    waterlines <- terra::as.polygons( waterlines, aggregate=TRUE )
    
    # subset only non-waterline (zero value polygon)
    non_waterline <- terra::subset( waterlines, waterlines$flowdir == 0)
    
    # buffer
    non_waterline <- terra::buffer(non_waterline, -1) #TUNE everything within 1m of waterlines gets excluded
    
    # plot waterlines to ensure correct tuning
    terra::plot(non_waterline, main = "Waterlines")
    
    # convert spatvector to st vector
    non_waterline <- sf::st_as_sf(non_waterline) 
    sf::st_crs(non_waterline) <- lidR::st_crs(all_minima)
    
    # crop to inverse of waterlines
    all_minima <- lidR::clip_roi( all_minima, non_waterline)
    
    message("Waterline points were removed.")
  }
  
  
  
  # GET MINIMA METRICS ------------------------------------------------------------------------------------------------
  
  # get minima data
  data_minima <- all_minima@data
  
  # get full cloud data
  data_all <- las_sub@data[, c("X","Y","Z","Classification")]
  
  # get point density (only class 2 and 7 points, if classes were filtered)
  h <- las_sub@header@PHB
  n <- h[["Number of point records"]]
  area <- (h[["Max X"]] - h[["Min X"]]) * (h[["Max Y"]] - h[["Min Y"]])
  density <- n / area
  
  # get estimated k value (number of points needed to accomplish radius value decided earlier)
  # this value is overestimated using *1.2 so then i can clip neighborhood using radius and get the actual ROI-resembling neighborhood i want
  k_est <- ceiling(pi * radius^2 * density *1.2) #TUNE overestimation
  
  # find neighbors in full cloud for each minima
  # important to compute neighbors in 2D space instead of 3D, hence the use of X and Y, not Z
  knn <- FNN::get.knnx(
    data = data_all[,c("X","Y")], 
    query = data_minima[,c("X","Y")], 
    k = k_est
  ) 
  message("Nearest neighbors of local minima were computed.")
  
  # set metrics depending on method
  if (method == "simple") {
    metrics <- names(metric_thresholds)
  } else if (method == "model") {
    metrics <- attr( model, "metrics")
  }
  
  # create empty output dataframe 
  minima_metrics <- data.frame(matrix(ncol = length(metrics), nrow = 0))
  colnames(minima_metrics) <- metrics
  
  message("Computing metrics...")
  
  # initialize progress bar
  n <- nrow(data_minima)
  pb <- utils::txtProgressBar(min = 0, max = n, style = 3)
  
  # compute metrics of each minima point 
  # this obtains the same metrics as the metrics_from_roi() function, but using nearest neighbors instead of 
  # using ROIs, which are impossibly slow to set for many thousands of candidate points
  for (id in seq_len(n)){
    
    # get neighbor indexes
    neighbor_idx <- knn$nn.index[id, ]
    
    # get neighbor distances to center/minima
    neighbor_dists <- knn$nn.dist[id, ]
    
    # subset neighbor idx and dists by radius
    inside_radius <- neighbor_dists < radius
    neighbor_idx <- neighbor_idx[inside_radius]
    neighbor_dists <- neighbor_dists[inside_radius]
    
    # get neighbor point data
    neighbor_pts <- data_all[ neighbor_idx , ]
    
    # subset ground points 
    is_ground <- neighbor_pts$Classification == 2
    ground_pts <- neighbor_pts[is_ground,]
    
    # subset dists only respective to ground points
    dists <- neighbor_dists[is_ground]
    
    # fit plane to ground surface: Z = a + bX + cY
    fit <- stats::.lm.fit(cbind(1, ground_pts$X, ground_pts$Y), ground_pts$Z)
    coefs <- fit$coefficients
    
    # get z of minima
    z_minima <- data_minima[id, "Z"]
    
    
    
    ## GET METRICS ------------------------------------------------------------------------------------------------
      
    # creating a list with a function for each metric, so i can choose which ones to call
    metric_funs <- list(
      
      # depth to plane
      depth_plane = function() coefs[1] + coefs[2]*data_minima$X[id] + coefs[3]*data_minima$Y[id] - z_minima,
      
      # depth to mean
      depth_mean = function() mean( ground_pts$Z ) - z_minima,
      
      # depth to half-radius mean (to look for holes at a smaller scale)
      # the way this metric is computed for the training data in train_model() used ROI and max_dist instead of radius
      # this is a very small skew in the data, but should be unimportant
      depth_half_radius_mean = function() mean( ground_pts$Z[ dists < radius/2 ] ) - z_minima,
      
      # depth to weighted mean
      # making points in a certain radius around minima have 0 contribution (those which are likely to also be inside entrance)
      # the way this metric is computed for the training data in train_model() used ROI and max_dist instead of radius
      # this is a very small skew in the data, but should be unimportant
      depth_w_mean = function(){
        weights <- ifelse(
          dists < 1, #TUNE 1m meter around entrance gives 0 contribution
          0,
          radius - dists # closer has higher contribution
        )
        stats::weighted.mean( ground_pts$Z, weights ) - z_minima
      },
      
      # calculate slope from plane
      slope = function() atan(sqrt(coefs[2]^2 + coefs[3]^2)) * 180 / pi,
      
      # other points values
      intensity = function() data_minima$Intensity[id],
      return_number = function() data_minima$ReturnNumber[id],
      R = function() data_minima$R[id],
      G = function() data_minima$G[id],
      B = function() data_minima$B[id],
      NIR = function() data_minima$NIR[id]
    )
    
    # outputting only selected metrics
    minima_metrics[id,] <- as.data.frame( lapply(metric_funs[metrics], function(f) f() ) )
    
    # update progress bar
    if (id %% 1000 == 0 || id == n) {
      utils::setTxtProgressBar(pb, id)
    }
  }
  
  message("Local minima metrics were computed.")
  
  
  
  # APPLYING METRIC THRESHOLDS ------------------------------------------------------------------------------------------------
  
  if (method == "simple"){
    
    # check which thresholds respected
    keep <- sweep(minima_metrics, 2, as.numeric(metric_thresholds), `>`)
    
    # only keep if all thresholds respected
    keep <- rowSums(keep) == ncol(keep)
    
    # build a per-point string with computed metric values (used in "simple" method exports)
    metrics_str <- apply(minima_metrics, 1, function(row) {
      paste(names(row), round(row, 2), sep = "=", collapse = "; ")
    })
    
    message( sum(keep), " out of ", length(keep), " local minima respected all thresholds and were kept.")
  }
  
  
  
  # PROJECT MODEL ON MINIMA METRICS ------------------------------------------------------------------------------------------------
  
  if (method == "model"){
    
    # project model
    data_minima$likelihood <- stats::predict( model, newdata = minima_metrics, type = "response" )
    
    # make NAs zero
    data_minima$likelihood[ is.na(data_minima$likelihood) ] <- 0
    
    # get coordinates of minima above certain score threshold
    keep <- data_minima$likelihood > score_threshold

    message( sum(keep), " out of ", length(keep), " local minima respected the ", score_threshold, " model score threshold and were kept.")
  }

  # check if nothing passed the thresholds
  if (!any(keep)) {
    message("No local minima respected the thresholds, so there are no predictions to export. Try less strict thresholds.")
    return(invisible(NULL))
  }
  
  
  
  # ELIMINATING POSITIVES RESPECTIVE TO SAME CAVE ------------------------------------------------------------------------------------------------
  
  # cluster based on XY
  cl <- dbscan::dbscan( data_minima[ keep, c("X","Y")], minPts = 1, eps = radius/2) #TUNE eps is minimum distance between points to keep both: can be large, since up to neighborhood radius any secondary deep points will still be seen in the neighborhood of deepest point
  
  # only keep lowest z in each cluster
  lowest_of_cluster <- stats::ave( data_minima[ keep, "Z"], cl$cluster, FUN = function(z) z == min(z) )
  
  # tricky step to input lowest_of_cluster TRUE/FALSE into keep's TRUE's
  keep[keep] <- as.logical(lowest_of_cluster)
  
  message( sum(keep), " of the above are unique. These are the final positives.")
  

  
  
  # PLOT ALL FINAL POSITIVES ------------------------------------------------------------------------------------------------

  # convert final positives to sf
  pts <- sf::st_as_sf(
    data_minima[keep, ],
    coords = c("X", "Y"),
    crs = lidR::wkt(las_sub)
  )
  
  # make mask and conversions from spatextent to st vector
  mask2 <- terra::ext(all_minima)
  mask2 <- terra::as.polygons(mask2)    
  mask2 <- sf::st_as_sf(mask2) 
  sf::st_crs(mask2) <- lidR::st_crs(all_minima)
  
  # get satellite image 
  sat <- tryCatch(
    maptiles::get_tiles(mask2, provider = "Esri.WorldImagery", crop = TRUE),
    error = function(e) {
      message("Satellite background could not be downloaded (", conditionMessage(e), "). Plotting points without it.")
      NULL
    }
  )
  
  # plot
  if (!is.null(sat)) {
    terra::plotRGB(sat)
    graphics::plot(sf::st_geometry(pts), add = TRUE, pch = 20, col = "red", cex = 1.5)
  } else {
    graphics::plot(sf::st_geometry(pts), pch = 20, col = "red", cex = 1.5)
  }

  
  
  # CASE-BY-CASE INSPECTION ------------------------------------------------------------------------------------------------
  # at this point, a plotting window will appear on the right of the screen. You should minimize RStudio's window to the left, so they are side by side.
  
  # get ROI's of final positives
  keep_xs <-  data_minima[keep, ]$X
  keep_ys <- data_minima[keep, ]$Y
  message("Getting ROI's...")
  keep_rois <- lidR::clip_circle( 
    las, 
    keep_xs, 
    keep_ys , 
    radius = radius
    )
  
  # get scores (model method) or metrics (simple method) of final positives
  if (method == "model") { 
    keep_scores <- data_minima[keep, ]$likelihood
    keep_metrics <- rep(NA_character_, length(keep_rois))
  } else {
    keep_scores <- rep( NA, length(keep_rois))
    keep_metrics <- metrics_str[keep]
  }
  
  # vector to store decisions
  decisions <- rep( NA, length(keep_rois))
  
  if (inspection){
    message(  
"Case-by-case inspection starting...
Minimize R to the left of the screen so you can see the plot window at the same time.
Label each point with a code, based on what you think its the potential. 
The codes are:
  empty (just enter): No potential - ignore;
  1: Isolated point, probable noise - only check if intercepted;
  2: Low potential - only check if intercepted;
  3: Medium potential - check if possible;
  4: High potential - check at all cost.
Green points are vegetation. If there's a lot of green, it might mean access is challenging."
    )   
  }

  for ( i in seq_along(keep_rois)) {
    
    ## ISOLATED POINT? ------------------------------------------------------------------------------------------------
    
    # get dataframe with point data
    pts <- keep_rois[[i]]@data[,c("X","Y","Z","Classification")]
      
    # subset points classified as "ground" (2) and as "noise" (7)
    # otherwise just use all points
    pts <- pts[ pts$Classification == 2 | pts$Classification == 7, ]

    # subset ground points to fit plane
    ground_pts <- pts[pts$Classification == 2, ]

    # fit plane: Z = a + bX + cY
    fit <- stats::lm(Z ~ X + Y, data = ground_pts)
    
    # predicted plane z values
    pts$Z_plane <- stats::predict(fit, newdata = pts[,c("X","Y")] )
    
    # residuals (negative means below plane)
    pts$residual <- pts$Z - pts$Z_plane
    
    # point lowest below plane
    id_low <- which.min(pts$residual)
    
    # get 2D distances of all points to cave point
    pts$dists <- sqrt(
      (pts$X - pts$X[id_low])^2 +
        (pts$Y - pts$Y[id_low])^2
    )
    
    # get residuals 
    residuals <- pts$residual
    residuals_near <- pts$residual[ pts$dists < 3  ] #TUNE "near" area defined using 3m radius
    
    # get outliers
    outliers <- grDevices::boxplot.stats( residuals, coef = 3 )$out #TUNE coef, larger coef restrics outlier definition
    
    # get extreme outliers
    extreme_outliers <- grDevices::boxplot.stats( residuals, coef = 5 )$out #TUNE coef, larger coef restrics outlier definition
    
    # exclude outliers with positive residuals (walls)
    outliers <- outliers[outliers < 0]
    extreme_outliers <- extreme_outliers[extreme_outliers < 0]
    
    # check if cave point is extreme outlier
    is_extreme_outlier <- pts$residual[id_low] %in% extreme_outliers
    
    # check if any of the no vegetation residuals near, except the cave, is an outlier
    any_outliers_near <- any( residuals_near[ !(pts$residual[id_low] == residuals_near) ] %in% outliers )
    
    # check if cave point is extreme outlier AND there are no other negative outliers
    isolated <- (is_extreme_outlier & !any_outliers_near)*1
    
    
    
    ## APPLY ISOLATED POINTS POLICY, PLOT, AND LABEL ------------------------------------------------------------------------------------------------
    
    if ( isolated & (isolated_policy == "exclude") ){
      
      decisions[i] <- "auto_isolated_exclude"
      message("Index ", i, " was an isolated point and was automatically excluded.")
      
    } else if ( isolated & (isolated_policy == "autolabel") ){
      
      decisions[i] <- "1"
      message("Index ", i, " was an isolated point and was automatically labeled as 1.")
      
    } else {
      
      if (inspection){
        
        roi <- keep_rois[[i]]
        
        # getting class colors
        cols <- unname(class_colors[as.character(roi$Classification)])
        cols[is.na(cols)] <- "gray"
        
        # plot based on point classification
        rgl::open3d()
        rgl::plot3d(
          roi@data$X,
          roi@data$Y,
          roi@data$Z,
          col = cols,
          size = 3,
          xlab = "X",
          ylab = "Y",
          zlab = "Z",
          aspect = "iso"
        )

        # change window size
        rgl::par3d(windowRect = c(800, 100, 1520, 800))
        
        # side view
        rgl::view3d(theta = 180, phi = 90)
        
        # query user and register answer
        if (method=="model"){
          if (isolated){
            decisions[i] <- readline(prompt = paste("Index", i, " - Score", round(keep_scores[i],2),"- This seems to be an isolated point (1) - Potential? (1/2/3/4): "))
          } else {
            decisions[i] <- readline(prompt = paste("Index", i, " - Score", round(keep_scores[i],2),"- Potential? (1/2/3/4): "))
          }
        } else {
          if (isolated){
            decisions[i] <- readline(prompt = paste("Index", i,"- This seems to be an isolated point (1) - Potential? (1/2/3/4): "))
          } else {
            decisions[i] <- readline(prompt = paste("Index", i, "- Potential? (1/2/3/4): "))
          }
        }
        
        # close window
        rgl::close3d()
        
      } else {
        decisions[i] <- "3"
        message("Index ", i, " was automatically labeled as 3.")
      }
    }
  }
  message("All points were labeled.")
  
  
  
  # EXPORT ------------------------------------------------------------------------------------------------
  
  prediction_id <-format(Sys.time(), "%Y%m%d%H%M")
  
  # build a string with settings
  settings_str <- paste0(
    "method=", method,
    "; radius=", radius,
    "; isolated_policy=", isolated_policy,
    "; remove_edges=", remove_edges,
    "; remove_waterlines=", remove_waterlines,
    "; inspection=", inspection,
    if (method == "model") paste0("; score_threshold=", score_threshold) else "",
    if (method == "simple") paste0("; metric_thresholds=", paste(names(metric_thresholds), metric_thresholds, sep = "=", collapse = ",")) else ""
  )
  
  # get coordinates and decision value of candidate points
  coords_export <- data.frame( 
    id = which(keep), 
    prediction = rep(prediction_id, length(keep_rois)),
    method = rep(method, length(keep_rois)),
    settings = rep( settings_str, length(keep_rois)),
    score = keep_scores,
    metrics = keep_metrics,
    X = keep_xs,
    Y = keep_ys, 
    label = decisions,
    success = rep(strrep(" ", 1), length(keep_rois)),
    desc = rep(strrep(" ", 50), length(keep_rois))
  )
  
  # subsetting points with positive label
  coords_export <- coords_export[ coords_export$label %in% c("1","2","3","4") , ]
  
  # create vector
  vect_export <- terra::vect( 
    coords_export, 
    geom = c("X", "Y"),
    crs = lidR::wkt(las))

  # shp
  dir.create(paste0( here::here("output", paste0("prediction_", prediction_id), "shp")), recursive = TRUE)
  terra::writeVector( vect_export, filename = here::here( "output", paste0("prediction_", prediction_id), "shp", paste0(prediction_id, ".shp" )))
  
  # kml
  kml_export <- vect_export[, "label"]
  kml_export$Name <- as.character(kml_export$label)
  kml_export$label <- NULL
  terra::writeVector( 
    kml_export, 
    filename = here::here( "output", paste0("prediction_", prediction_id), paste0(prediction_id, ".kml" ))
    )
  
  message("Final points were exported to the prediction_", prediction_id, " folder." )
}
